    A=p[0]*t**p[1]+p[2]*t
    B=1+p[3]*P+p[4]*P**2
    return -A*B
def m2(p):
    return -(p[0]*t**p[1]) - (p[2]*P**p[3]) - p[4]*P**2*t**p[5]
def m3(p):
    return -(p[0]*t**p[1])*(1+p[2]*P**p[3]) - p[4]*P**2
